    "id": "suncorp-10",
    "content": "## Section 2: Contents Sub-Limits Schedule\n\nThe following maximum limits apply per claim and sit within your total Contents Sum Insured:\n\n| Item Category | Standard Policy Sub-Limit | Optional Extended Cover Available? |\n| :--- | :--- | :--- |\n| **Jewelry and Watches** | $2,500 total (max $1,000 per individual item) | Yes, when individually specified and valued |\n| **Works of Art, Paintings & Curios** | $5,000 total | Yes, with verified valuation certificate |\n| **Collections (Stamps, Coins, Medals)** | $2,000 total | Yes, with listed schedule |\n| **Cash, Bank Notes & Gift Cards** | $500 total | No optional increase available |\n| **Bicycles & E-Scooters** | $1,500 per item | Yes, specified on certificate |\n| **Home Office Equipment** | $10,000 total | Yes, up to $20,000 |\n\n---",
