    "content": "### Exclusion 2: Alcohol, Drugs and Intoxication\nWe do not cover loss, damage, or liability if the driver of your vehicle:\n- Has a Blood Alcohol Concentration (BAC) exceeding the statutory legal limit prescribed in the state or territory of occurrence; or\n- Is under the influence of any drug or intoxicating substance; or\n- Refuses to submit to a lawful breath, blood, or urine test required by law enforcement.\n\n---",
