    "content": "### Exclusion 3: Unroadworthy or Damaged Condition\nWe do not cover loss, damage, or liability if your vehicle is being driven in an unroadworthy, unsafe, or overloaded condition where such condition contributed to the accident, and you knew or ought reasonably to have known of the unroadworthy condition.\n\n---",
