    "id": "allianz-14",
    "content": "## Section 3: Additional Benefits & Sub-Limits Schedule\n\nThe following sub-limits apply per incident and sit within your vehicle Agreed Value or Market Value:\n\n| Benefit Category | Standard Policy Sub-Limit | Optional Increase Available? |\n| :--- | :--- | :--- |\n| **Hire Car Following Theft** | $100 per day (max 21 days / $2,100 total) | Yes, optional hire car for any incident |\n| **Emergency Accommodation & Travel** | Up to $1,000 total (if accident >100km from home) | No |\n| **Personal Effects in Vehicle** | Up to $1,000 total ($500 max per item) | Yes, specified contents addition |\n| **Child Safety Seats & Baby Capsules** | Up to $500 per seat (replacement cost) | No |\n| **Towing and Reasonable Storage** | Reasonable and necessary costs to nearest repairer | Included automatically |\n| **Windscreen & Window Glass Only** | 1 replacement per policy year without excess | Optional cover endorsement |\n| **Trailer Cover** | Up to $1,000 or market value | Yes, specified trailer endorsement |\n\n---",
