    "id": "allianz-15",
    "content": "## Section 4: Excess Schedules & Deductibles\n\nAn excess is the amount you contribute towards each claim:\n\n| Excess Type | Standard Amount | Applicable Conditions |\n| :--- | :--- | :--- |\n| **Basic Policy Excess** | As stated on Policy Schedule (default $850) | Applies to all claims unless non-fault |\n| **Age Excess (Driver aged under 21)** | $600 additional excess | Applies on top of Basic Excess |\n| **Age Excess (Driver aged 21 to 24)** | $500 additional excess | Applies on top of Basic Excess |\n| **Inexperienced Driver Excess** | $400 additional excess | Driver aged 25+ licensed <2 years |\n| **Undisclosed / Unlisted Driver Excess** | $1,000 additional excess | Driver not named on certificate |\n\n---",
