    "id": "faq-suncorp-2",
    "content": "## Question 1: How does Suncorp define a flood under the Insurance Contracts Regulations?\n**Insurer:** SUNCORP | **ID:** `suncorp-home-001` [Topics: flood, prescribed-definition, embargo]\n\n### Official Guidance\nUnder the Insurance Contracts Regulations 2012 (Cth), Suncorp defines flood as the covering of normally dry land by water that has escaped or been released from the normal confines of any natural watercourse, lake, reservoir, canal, or dam. Suncorp policies exclude flood damage occurring in the first 72 hours of policy purchase.\n\n*Canonical Source:* [https://www.suncorp.com.au/insurance/home-contents.html](https://www.suncorp.com.au/insurance/home-contents.html)\n\n---",
