    "id": "faq-suncorp-3",
    "content": "## Question 2: What is Suncorp's standard sub-limit for jewelry and watches?\n**Insurer:** SUNCORP | **ID:** `suncorp-home-002` [Topics: jewelry, sub-limits, contents]\n\n### Official Guidance\nUnder Suncorp Classic Home Contents, jewelry and watches have a standard policy sub-limit of $2,500 total, with a maximum of $1,000 for any single item, unless individually listed on the policy certificate.\n\n*Canonical Source:* [https://www.suncorp.com.au/insurance/home-contents.html](https://www.suncorp.com.au/insurance/home-contents.html)\n\n---\n\n\n### Regulatory Warning (Corporations Act 2001 Section 949A)\n⚠️ General Advice Warning: This information is general factual information only and does not take into account your personal objectives, financial situation, or needs. Before making any financial decision, you should read the relevant Product Disclosure Statement (PDS) and Target Market Determination (TMD) and seek independent advice.",
