    "id": "faq-allianz-2",
    "content": "## Question 1: Does Allianz Home and Contents insurance cover flood damage?\n**Insurer:** ALLIANZ | **ID:** `allianz-home-001` [Topics: flood, embargo, exclusions]\n\n### Official Guidance\nYes, flood and rainwater run-off are covered under Allianz Home and Contents Insurance. However, a 72-hour exclusion period applies: Allianz does not provide cover for loss or damage caused by flood, flood water combined with run-off, cyclone, or bushfires during the first 72 hours after purchasing a new policy or increasing cover.\n\n*Canonical Source:* [https://www.allianz.com.au/home-insurance/home-and-contents.html](https://www.allianz.com.au/home-insurance/home-and-contents.html)\n\n---",
