    "id": "faq-allianz-3",
    "content": "## Question 2: Do I have to pay two excesses if both my building and contents are damaged?\n**Insurer:** ALLIANZ | **ID:** `allianz-home-002` [Topics: excess, combined-policy]\n\n### Official Guidance\nNo. When you combine both Home Building and Contents cover under one policy, you generally only pay one excess if your building and contents are damaged by the same insured event.\n\n*Canonical Source:* [https://www.allianz.com.au/home-insurance/home-and-contents.html](https://www.allianz.com.au/home-insurance/home-and-contents.html)\n\n---",
