    "id": "faq-allianz-4",
    "content": "## Question 3: Are home renovations covered under my policy?\n**Insurer:** ALLIANZ | **ID:** `allianz-home-003` [Topics: renovations, exclusions, building]\n\n### Official Guidance\nAllianz covers your home while renovations, alterations, demolition, or repairs costing up to $75,000 are underway. If the planned work costs more than $75,000, you must notify Allianz before work begins. Allianz does not cover damage caused by the renovation work itself or water entering through openings created by the work.\n\n*Canonical Source:* [https://www.allianz.com.au/home-insurance/home-and-contents.html](https://www.allianz.com.au/home-insurance/home-and-contents.html)\n\n---",
