    "id": "faq-allianz-5",
    "content": "## Question 4: Does Allianz cover temporary accommodation for pets?\n**Insurer:** ALLIANZ | **ID:** `allianz-home-004` [Topics: temporary-accommodation, pets, claims]\n\n### Official Guidance\nYes. If your home building is damaged by an insured event and becomes uninhabitable, Allianz pays reasonable temporary accommodation costs for you and your pets, up to 10% of your building or contents sum insured.\n\n*Canonical Source:* [https://www.allianz.com.au/home-insurance/home-and-contents.html](https://www.allianz.com.au/home-insurance/home-and-contents.html)\n\n---",
