    "id": "faq-allianz-6",
    "content": "## Question 5: What is the sub-limit for replacement of locks after a burglary?\n**Insurer:** ALLIANZ | **ID:** `allianz-home-005` [Topics: burglary, locks, sub-limits]\n\n### Official Guidance\nAllianz will pay up to $2,000 to replace external door or window locks if your keys are stolen following a theft or burglary.\n\n*Canonical Source:* [https://www.allianz.com.au/home-insurance/home-and-contents.html](https://www.allianz.com.au/home-insurance/home-and-contents.html)\n\n---",
