    "id": "faq-allianz-7",
    "content": "## Question 6: Are electric bikes (eBikes) and eScooters covered?\n**Insurer:** ALLIANZ | **ID:** `allianz-home-006` [Topics: escooter, ebike, liability, sub-limits]\n\n### Official Guidance\nAllianz covers eBikes and eScooters damaged at home by an insured event (or away from home if Portable Contents is added), provided they have a maximum speed of 25 km/h and are not used for racing or competition. However, Allianz does NOT cover legal liability for eBikes or eScooters (e.g. if you injure someone or cause a battery fire).\n\n*Canonical Source:* [https://www.allianz.com.au/home-insurance/home-and-contents.html](https://www.allianz.com.au/home-insurance/home-and-contents.html)\n\n---",
