    "id": "faq-allianz-8",
    "content": "## Question 7: What happens if my house is unoccupied for more than 60 days?\n**Insurer:** ALLIANZ | **ID:** `allianz-home-007` [Topics: unoccupied, conditions, exclusions]\n\n### Official Guidance\nYou must inform Allianz if your home building has not been lived in, or will not be lived in, for more than 60 consecutive days. Failure to notify Allianz may result in claims being declined.\n\n*Canonical Source:* [https://www.allianz.com.au/home-insurance/home-and-contents.html](https://www.allianz.com.au/home-insurance/home-and-contents.html)\n\n---",
