    "id": "faq-allianz-9",
    "content": "## Question 8: How does car insurance work in Australia?\n**Insurer:** ALLIANZ | **ID:** `allianz-001`\n\n### Official Guidance\nThere are many types of private motor vehicle insurance in Australia, such as comprehensive, third party property damage, third party property damage fire and theft, and compulsory third party (CTP) which differs in each state and territory. We offer Comprehensive Car Insurance and Third Party Property Damage Car Insurance in all states. We also offer CTP Insurance in NSW, QLD, and SA. Compulsory Third Party (CTP) Insurance is a mandatory policy that generally covers anyone who drives your vehicle (including yourself) for injuries caused to others in an at-fault motor accident. Third Party Property Damage Car Insurance helps cover the cost of accidentally damaging someone else’s car or property. Damage to your own car is not covered. Comprehensive Car Insurance covers your car, plus damage you cause to other people’s cars or property. Third Party Property Damage and Comprehensive Car Insurance aren’t mandatory in Australia, but there are benefits to having them. If you choose not to take out either, you may be responsible for the cost of any damage you caused to your car or third party property. If you aren't sure whether you need Third Party Property Damage Car Insurance or Comprehensive Car Insurance, visit our car insurance comparison page to find the right cover for you. We also offer Caravan and Trailer Insurance in Australia.\n\n*Canonical Source:* [https://www.allianz.com.au/car-insurance.html#](https://www.allianz.com.au/car-insurance.html#)\n\n---",
