    "id": "faq-allianz-11",
    "content": "## Question 10: What is excess in car insurance?\n**Insurer:** ALLIANZ | **ID:** `allianz-003`\n\n### Official Guidance\nExcess is the amount you’ll need to pay towards the cost of a claim. Your policy documentation will show two excess amounts: Basic excess and Under 25 Driver excess. Basic excess is the amount that applies to each claim that you make. Under 25 Driver excess is an amount added to your Basic excess if the driver of your car is under the age of 25 at the time an incident occurs. You can reduce the amount of your Under 25 Driver excess by listing the youngest driver on your policy but this may also increase your premium. If you or the driver of your car are involved in an accident and aren’t at fault and can provide us with the responsible party’s details, you may not have to pay an excess. For more information, read our car insurance excess guide. View the Product Disclosure Statement (PDS) for more information about your excess.\n\n*Canonical Source:* [https://www.allianz.com.au/car-insurance.html#](https://www.allianz.com.au/car-insurance.html#)\n\n---",
