    "id": "faq-allianz-12",
    "content": "## Question 11: Can I reduce my premium?\n**Insurer:** ALLIANZ | **ID:** `allianz-004`\n\n### Official Guidance\nIf you have Allianz Comprehensive Car Insurance, you may be able to reduce your premium by increasing your basic excess. You may have to pay a higher excess at claim time.\n\n*Canonical Source:* [https://www.allianz.com.au/car-insurance.html#](https://www.allianz.com.au/car-insurance.html#)\n\n---",
