    "id": "faq-allianz-13",
    "content": "## Question 12: What if I have a car accident?\n**Insurer:** ALLIANZ | **ID:** `allianz-005`\n\n### Official Guidance\nIf you have Allianz Comprehensive Car Insurance: Contact police/ambulance if people are injured. Record the name, address, phone number, email address, licence number, and insurer of other drivers involved. Record the registration numbers, make, and model of the vehicles involved. Try to get names, addresses, phone numbers, and email addresses of witnesses. Where possible, try to get photos of any damages caused and vehicles involved where it’s safe to do so. If your car isn’t driveable, call us and if you have comprehensive car insurance, we’ll arrange for it to be towed somewhere safe and cover the reasonable costs of towing and storage. Make sure you have the address details so that you can let us know where your car is located. For more information, read our article on what to do after a car accident.\n\n*Canonical Source:* [https://www.allianz.com.au/car-insurance.html#](https://www.allianz.com.au/car-insurance.html#)\n\n---",
