    "id": "faq-allianz-14",
    "content": "## Question 13: What if my car is stolen?\n**Insurer:** ALLIANZ | **ID:** `allianz-006`\n\n### Official Guidance\nIf your vehicle has been stolen, report it to the police as soon as possible and record the police report number when it’s issued to you. Once the Police have been notified, if you have Allianz Comprehensive Car Insurance submit a claim online, or call our claims department on 13 10 13 and one of our friendly consultants will take you through the claims process.\n\n*Canonical Source:* [https://www.allianz.com.au/car-insurance.html#](https://www.allianz.com.au/car-insurance.html#)\n\n---",
