    "id": "faq-nrma-3",
    "content": "## Question 2: How long does NRMA pay for temporary accommodation after an insured event?\n**Insurer:** NRMA | **ID:** `nrma-home-002` [Topics: temporary-accommodation, claims, limits]\n\n### Official Guidance\nNRMA pays for reasonable temporary accommodation costs for up to 1 year under the Home Buildings and Contents Standard policy (up to 10% of sum insured), or up to 2 years under Home Buildings and Contents Plus (up to 20% of sum insured), if your home is unliveable.\n\n*Canonical Source:* [https://www.nrma.com.au/home-insurance](https://www.nrma.com.au/home-insurance)\n\n---",
