    "id": "faq-nrma-4",
    "content": "## Question 3: Does NRMA cover damage from actions of the sea or high tides?\n**Insurer:** NRMA | **ID:** `nrma-home-003` [Topics: actions-of-the-sea, flood, exclusions]\n\n### Official Guidance\nNo. NRMA explicitly does not cover loss or damage caused by actions of the sea, such as high tides and tidal waves. Escaped water from shower recesses or erosion is also excluded.\n\n*Canonical Source:* [https://www.nrma.com.au/home-insurance](https://www.nrma.com.au/home-insurance)\n\n---",
