    "id": "faq-nrma-5",
    "content": "## Question 4: Does NRMA guarantee the workmanship of repairs?\n**Insurer:** NRMA | **ID:** `nrma-home-004` [Topics: repairs, guarantee, claims]\n\n### Official Guidance\nYes. NRMA offers a lifetime guarantee on the workmanship of all authorized repairs completed through their network of approved partner repairers and suppliers.\n\n*Canonical Source:* [https://www.nrma.com.au/home-insurance](https://www.nrma.com.au/home-insurance)\n\n---\n\n\n### Regulatory Warning (Corporations Act 2001 Section 949A)\n⚠️ General Advice Warning: This information is general factual information only and does not take into account your personal objectives, financial situation, or needs. Before making any financial decision, you should read the relevant Product Disclosure Statement (PDS) and Target Market Determination (TMD) and seek independent advice.",
