    "id": "faq-aami-2",
    "content": "## Question 1: Can I remove flood cover from my AAMI Home Insurance policy to lower my premium?\n**Insurer:** AAMI | **ID:** `aami-home-001` [Topics: flood, embargo, pricing]\n\n### Official Guidance\nNo. Flood cover is automatically included on AAMI Home Insurance policies and cannot be removed. However, AAMI does not cover flood damage for the first 72 hours of a new policy (embargo period).\n\n*Canonical Source:* [https://www.aami.com.au/home-insurance.html](https://www.aami.com.au/home-insurance.html)\n\n---",
