    "id": "faq-aami-5",
    "content": "## Question 4: Do I need to add a learner driver to my policy?\n**Insurer:** AAMI | **ID:** `aami-002`\n\n### Official Guidance\nDon't stress - there's no need to update your policy to include a learner driver. They're automatically covered under your insurance policy when you make a claim, as long as there's an insured, licensed driver in the front passenger seat with them when they're driving. If a learner, young or inexperienced driver is driving at the time of an incident, you may have to pay an additional excess. Check your policy documents to find out what excesses apply to your cover.Learn more about Car Insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/do-i-need-to-add-a-learner-driver-to-my-policy.html](https://www.aami.com.au/faq/do-i-need-to-add-a-learner-driver-to-my-policy.html)\n\n---",
