    "id": "faq-aami-6",
    "content": "## Question 5: Am I covered if I use my car for ridesharing services like Uber?\n**Insurer:** AAMI | **ID:** `aami-003`\n\n### Official Guidance\nIf you're an AAMI Comprehensive car insurance policy holder, your cover can extend to ridesharing services like Uber, DiDi and Ola. This is when the owner of the car, or a driver listed on the policy, drives the car for passengers for a fee.If you're considering taking up ridesharing, you must let us know. You can do this easily via your My Account through these simple steps:Log in to your My Account and select your car insurance policy.Click ‘Update policy’ and then scroll down to ‘Car usage’.Select the ‘Ridesharing’ box from the list.Alternatively, you can call 13 22 44 to speak to one of our customer service agents. It's important to note that this may affect your premium. Learn more about Comprehensive Car Insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/am-i-covered-if-i-use-mPfaqy-car-for-ridesharing-services-like-uber.html](https://www.aami.com.au/faq/am-i-covered-if-i-use-mPfaqy-car-for-ridesharing-services-like-uber.html)\n\n---",
