    "id": "faq-aami-7",
    "content": "## Question 6: What discounts can I get on my policy?\n**Insurer:** AAMI | **ID:** `aami-004`\n\n### Official Guidance\nAlthough AAMI doesn’t offer a multi-policy and pension discounts, we do have a Safe Driver Rewards program, also known as a no claims bonus. It awards Comprehensive Car Insurance policy holders with benefits and rewards for every consecutive year they don’t make a claim. The longer you’ve been with AAMI and not made a claim, the better your discounts and rewards will be. If you’re looking for more ways to save on your insurance policy, this article has a lot of useful information.\n\n*Canonical Source:* [https://www.aami.com.au/faq/what-discounts-can-i-get-on-my-policy.html](https://www.aami.com.au/faq/what-discounts-can-i-get-on-my-policy.html)\n\n---",
