    "id": "faq-aami-8",
    "content": "## Question 7: Are there any types of caravans you don't insure?\n**Insurer:** AAMI | **ID:** `aami-005`\n\n### Official Guidance\nAAMI offers insurance for standard caravans – that is, non-motorised vehicles, usually with two wheels that can be towed by a car. That means we don’t offer insurance for the following caravan types or uses:Campervans (motorised caravans)Homemade caravansMotorhomes Trailers (aside from camper trailers)Caravans used as courtesy vansCaravans converted to sell food or beveragesCaravans converted to sell other goods e.g. flowersCaravans used as demonstration vansCaravans used for hire or rewardCaravans used for any business purposeCaravans used for any business or commercial purpose including carrying goods, used by caravan hire, trade or motor tradeCaravans used by home sharing schemes or short term/holiday rental accommodationLearn more about caravan insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/are-there-any-types-of-caravans-you-dont-insure.html](https://www.aami.com.au/faq/are-there-any-types-of-caravans-you-dont-insure.html)\n\n---",
