    "id": "faq-aami-9",
    "content": "## Question 8: How do I get a copy of my insurance certificate?\n**Insurer:** AAMI | **ID:** `aami-006`\n\n### Official Guidance\nIf you have an eligible AAMI policy, you can grab your Certificate of Insurance, or COI — from our Documents Hub. You just need to pop in your name, date of birth and phone number, and we’ll text you secure PIN that gives you access to your documents.Eligible policies are:Comprehensive Car InsuranceCTP InsuranceMotorcycle InsuranceCaravan InsuranceThird Party Property Damage Car InsuranceHome Building & Contents InsuranceHome Building InsuranceHome Contents InsuranceContents (Fire & Theft) InsuranceBuilding for Landlords InsuranceContents for Landlords InsuranceIf your policy isn’t on this list, give us a call on 13 22 44 and we can send you a copy of your certificate.\n\n*Canonical Source:* [https://www.aami.com.au/faq/how-do-i-get-a-copy-of-my-insurance-certificate.html](https://www.aami.com.au/faq/how-do-i-get-a-copy-of-my-insurance-certificate.html)\n\n---",
