    "id": "faq-aami-10",
    "content": "## Question 9: What does AAMI Home Assist provide?\n**Insurer:** AAMI | **ID:** `aami-007`\n\n### Official Guidance\nIf you have a home emergency at your insured address and you’ve added AAMI Home Assist to your policy at least 24 hours prior, we’ll dispatch a selected trade service to your insured address for a period of up to two hours to provide assistance. The 2 hours commences when the tradesperson arrives at your address.Learn more about home assist\n\n*Canonical Source:* [https://www.aami.com.au/faq/what-does-aami-home-assist-provide.html](https://www.aami.com.au/faq/what-does-aami-home-assist-provide.html)\n\n---",
