    "id": "faq-aami-11",
    "content": "## Question 10: Which driver's licences are accepted for AAMI policies?\n**Insurer:** AAMI | **ID:** `aami-008`\n\n### Official Guidance\nIf you're legally allowed to drive in Australia, and you have a permanent Australian address, you can purchase AAMI Car Insurance or be listed as a driver by someone who has.For drivers from overseas with international licences, this means that you can still take out an AAMI policy or be listed driver on someone else's policy, providing you comply with the laws in your state regarding driving with a non-Australian licence.Learn more about car insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/which-drivers-licences-are-accepted-for-aami-policies.html](https://www.aami.com.au/faq/which-drivers-licences-are-accepted-for-aami-policies.html)\n\n---",
