    "id": "faq-aami-13",
    "content": "## Question 12: What happens if my car is a total loss?\n**Insurer:** AAMI | **ID:** `aami-010`\n\n### Official Guidance\nIf you have comprehensive insurance your car becomes a total loss if:it is stolen and unrecovered after 14 days and we accept your claim for theft of your car; orit is uneconomical or unsafe to repair, including where the combined repair costs and salvage value are likely to be more than the amount covered by your policy.If your car is more than 2 years old, we pay the amount covered less any applicable deductions.For full details, please download the Comprehensive Car Insurance PDS and Additional Information Guide.If your car is less than 2 years old, and you bought it new, we'll replace it with a new car of the same make, model and series (if available within 90 days), or similar if not available. If you choose not to accept the replacement car, or where an agreement cannot be reached between us on a replacement car, or a replacement car cannot be supplied, we will pay you the amount covered on your certificate of insurance (less any deductions). See the PDS for full details.Learn more about Comprehensive Car Insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/what-happens-if-my-car-is-a-total-loss.html](https://www.aami.com.au/faq/what-happens-if-my-car-is-a-total-loss.html)\n\n---",
