    "id": "faq-aami-14",
    "content": "## Question 13: Do I need to tell you about any modifications or accessories to my car?\n**Insurer:** AAMI | **ID:** `aami-011`\n\n### Official Guidance\nModifications are alterations made to the manufacturer’s standard body, engine, suspension, wheels or paintwork of your car which may affect its performance, value, safety or appearance.An accessory is an addition to your car which does not enhance the performance or change the structure of the car.If you choose to insure for an amount covered, just check the amount you cover your car for is enough to also include the value of the insured accessories and modifications as described on your Certificate of Insurance.If you choose to insure for market value (and we agree), accessories and modifications permanently fitted to the vehicle will be included in determining the market value when you make a claim.Learn more about Car Insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/do-i-need-to-tell-you-about-any-modifications-or-accessories-to-my-car.html](https://www.aami.com.au/faq/do-i-need-to-tell-you-about-any-modifications-or-accessories-to-my-car.html)\n\n---",
