    "id": "faq-aami-15",
    "content": "## Question 14: How do I cancel my policy?\n**Insurer:** AAMI | **ID:** `aami-012`\n\n### Official Guidance\nI'm sorry you're thinking of cancelling! You can cancel your car (excl. CTP or MAI), home or landlord insurance via the AAMI virtual assistant. It's easy to get started, cancel your policy.For all other policies, contact us to talk to one of our specialists about cancelling.\n\n*Canonical Source:* [https://www.aami.com.au/faq/how-do-i-cancel-my-policy.html](https://www.aami.com.au/faq/how-do-i-cancel-my-policy.html)\n\n---",
