    "id": "faq-aami-16",
    "content": "## Question 15: Can I drive after surgery or caesarean?\n**Insurer:** AAMI | **ID:** `aami-013`\n\n### Official Guidance\nIf you, or the person driving, is on medication that may impair your judgment behind the wheel, including painkillers, you may not be covered by your car insurance policy. This includes if you’re still medicated after any surgery or procedure, including a caesarean (c-section), or you’re under medical advice not to drive. If you’re in an accident post-surgery, we’ll take into account whether the surgery impaired your ability to drive when we look at your claim. We’ll also consider whether medication has affected your ability to drive.To get a better idea of what is and isn’t covered, it’s best to read your PDS.Learn more about Car Insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/can-i-drive-after-surgery-or-caesarean.html](https://www.aami.com.au/faq/can-i-drive-after-surgery-or-caesarean.html)\n\n---",
