    "id": "faq-aami-17",
    "content": "## Question 16: Are trailers covered under my car insurance policy?\n**Insurer:** AAMI | **ID:** `aami-014`\n\n### Official Guidance\nTwo-wheel trailers attached to your car are covered by Comprehensive Car Insurance. As long as it’s attached to your car when the incident happens, we pay up to $1,000 for accidental damage. Theft of your attached trailer is also covered.Learn more about comprehensive car insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/are-trailers-covered-under-my-car-insurance-policy.html](https://www.aami.com.au/faq/are-trailers-covered-under-my-car-insurance-policy.html)\n\n---",
