    "id": "faq-aami-18",
    "content": "## Question 17: What's a make safe?\n**Insurer:** AAMI | **ID:** `aami-015`\n\n### Official Guidance\nA “make safe” is an urgent temporary repair carried out to secure the property and prevent further damage. For example, if there’s a leak in the roof, a repairer will attend and may put up a temporary patch or tarp to stop further water damage. A permanent solution will follow as the claim progresses.To have a make safe completed, contact your Claims Officer to appoint a repairer. If calling outside standard business hours, contact our after-hours team on 13 22 44, who can arrange a make safe after lodging your claim.\n\n*Canonical Source:* [https://www.aami.com.au/faq/whats-a-make-safe.html](https://www.aami.com.au/faq/whats-a-make-safe.html)\n\n---",
