    "id": "faq-aami-21",
    "content": "## Question 20: Where can I find my PDS?\n**Insurer:** AAMI | **ID:** `aami-018`\n\n### Official Guidance\nYour PDS (Product Disclosure Statement) provides all the nitty gritty details of your insurance policy. It’s important that you read through it if you’re considering taking out an AAMI insurance policy, or if you’re an existing policy holder and want to get more information. You can find all PDS documents, and other policy documents here: https://www.aami.com.au/policy-documents.html\n\n*Canonical Source:* [https://www.aami.com.au/faq/where-can-i-find-my-pds.html](https://www.aami.com.au/faq/where-can-i-find-my-pds.html)\n\n---",
