    "id": "faq-aami-24",
    "content": "## Question 23: Can I choose who repairs my car?\n**Insurer:** AAMI | **ID:** `aami-021`\n\n### Official Guidance\nTo make things simpler for you, AAMI takes care of the entire quote and repair process, using one of our preferred repairers. That means after you've lodged your claim, you can sit back, relax, and let us handle things. To join our preferred repairer network, repairers must hold the latest industry qualifications and consistently deliver the highest standard of workmanship, quality assurance and customer care. This means we only partner with accredited repairers that set the highest standards. That’s why our authorised repairs come with a lifetime guarantee to give you a little extra peace of mind. Learn more about AAMI Repairs and Replacements\n\n*Canonical Source:* [https://www.aami.com.au/faq/can-i-choose-who-repairs-my-car.html](https://www.aami.com.au/faq/can-i-choose-who-repairs-my-car.html)\n\n---",
