    "id": "faq-aami-27",
    "content": "## Question 26: How do I add Roadside Assist to my policy?\n**Insurer:** AAMI | **ID:** `aami-024`\n\n### Official Guidance\nRoadside Assist is available as an Optional Cover for an additional cost for AAMI Comprehensive Car Insurance policy holders. Key features of Roadside Assist include:No joining fees24 hour unlimited* roadside calloutsTowing 20kms from the breakdown location to an accredited repairer. If there is no accredited repairer within 20kms we will tow the vehicle to the nearest accredited repairer up to 100kms from the breakdown locationTo add it to your policy, simply call 13 22 44 or chat to online us via the Contact Us page. If you’re a new customer, you can add it as an Optional Cover for an additional cost during the quote process. Roadside Assist is available 24 hours after adding it to your policy.For emergency roadside assistance, please call 1800 154 810. *Terms and conditions for coverage apply.Learn more about roadside assistance\n\n*Canonical Source:* [https://www.aami.com.au/faq/how-do-i-add-roadside-assist-to-my-policy.html](https://www.aami.com.au/faq/how-do-i-add-roadside-assist-to-my-policy.html)\n\n---",
