    "id": "faq-aami-28",
    "content": "## Question 27: Is my mobile phone covered by my home insurance?\n**Insurer:** AAMI | **ID:** `aami-025`\n\n### Official Guidance\nMobile phones can be covered under your AAMI Contents Insurance for loss or damage caused by insured events such as fire, flood or theft when the loss or damage occurs at the insured address.If you’d like to cover your mobile for accidental damage or loss – both at and away from your home – consider adding optional Extra Cover Portable valuables cover to your AAMI Contents Insurance for an added premium.Need to make a claim? Lodge online or in the AAMI App, 24/7\n\n*Canonical Source:* [https://www.aami.com.au/faq/is-my-mobile-phone-covered-by-my-home-insurance.html](https://www.aami.com.au/faq/is-my-mobile-phone-covered-by-my-home-insurance.html)\n\n---",
