    "id": "faq-aami-29",
    "content": "## Question 28: Can I remove flood cover from my home insurance policy?\n**Insurer:** AAMI | **ID:** `aami-026`\n\n### Official Guidance\nFlood is automatically included and cannot be removed from your policy.If you removed flood cover from an existing policy, your certificate of insurance will show this limitation in your cover.\n\n*Canonical Source:* [https://www.aami.com.au/faq/can-i-remove-flood-cover-from-my-home-insurance-policy.html](https://www.aami.com.au/faq/can-i-remove-flood-cover-from-my-home-insurance-policy.html)\n\n---",
