    "id": "faq-aami-30",
    "content": "## Question 29: How do I change my address?\n**Insurer:** AAMI | **ID:** `aami-027`\n\n### Official Guidance\nChanging the address on your insurance is easy and can be done completely online. Simply log in to My Account, select ‘My policy list’ then ‘Update my policy’, and choose ‘Contact details’ under the ‘My personal details’ heading. Remember to double check that your mailing address is the correct one also. Please note: Life Insurance and Income Protection aren't currently supported online. Please call us on 13 22 44 if you need to change your address.\n\n*Canonical Source:* [https://www.aami.com.au/faq/how-do-i-change-my-address.html](https://www.aami.com.au/faq/how-do-i-change-my-address.html)\n\n---",
