    "id": "faq-aami-31",
    "content": "## Question 30: Am I covered in an at-fault car accident?\n**Insurer:** AAMI | **ID:** `aami-028`\n\n### Official Guidance\nThe extent to which you and your vehicle will be covered and if you can make a claim in an at-fault accident depends on your level of insurance. Read your PDS for conditions and exclusions. Generally, if you have:CTP Insurance, you’ll be covered for the costs of personal injury claims made against you in the event of a motor vehicle accident where pedestrians, cyclists, or other drivers are involved. This doesn’t include damage to your vehicle and the other driver’s, though.Third Party Property Damage Insurance, you may be covered for damage caused to another person’s vehicle or property, but you will not be covered for damage to your vehicle. If you have included Fire and Theft cover, you may be covered if your car is stolen or damaged by fire or attempted theft.Comprehensive Car Insurance, covers accidental damage to your vehicle, whether you’re at fault or not.Cover may vary from insurer to insurer or the state you live in. For more info, be sure to read your PDS.Learn more about Car Insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/am-i-covered-in-an-at-fault-car-accident.html](https://www.aami.com.au/faq/am-i-covered-in-an-at-fault-car-accident.html)\n\n---",
