    "id": "faq-aami-32",
    "content": "## Question 31: Can I cancel my ACT MAI Insurance?\n**Insurer:** AAMI | **ID:** `aami-029`\n\n### Official Guidance\nCancelling your MAI Insurance means cancelling your vehicle’s registration, which you can choose to do at any time. Once you’ve cancelled your registration, you won’t be allowed to drive your vehicle anymore.You can lodge your request to cancel at your nearest Access Canberra Service Centre. Learn more about MAI insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/can-i-cancel-my-act-mai-insurance.html](https://www.aami.com.au/faq/can-i-cancel-my-act-mai-insurance.html)\n\n---",
