    "id": "faq-aami-34",
    "content": "## Question 33: Does Excess-Free Glass cover any of my contents that contain glass, like vases, drinking glasses and TV screens?\n**Insurer:** AAMI | **ID:** `aami-031`\n\n### Official Guidance\nNo, accidental breakage of glass in any contents is excluded under Excess-free Glass cover.Refer to the PDS for more information.Learn more about excess-free glass cover\n\n*Canonical Source:* [https://www.aami.com.au/faq/does-excess-free-glass-cover-any-of-my-contents-that-contain-glass-like-vases-drinking-glasses-and-tv-screens.html](https://www.aami.com.au/faq/does-excess-free-glass-cover-any-of-my-contents-that-contain-glass-like-vases-drinking-glasses-and-tv-screens.html)\n\n---",
