    "id": "faq-aami-35",
    "content": "## Question 34: Am I covered for collisions with wildlife?\n**Insurer:** AAMI | **ID:** `aami-032`\n\n### Official Guidance\nAAMI Comprehensive Car Insurance may cover damage to your car in the event of a collision with animals and wildlife, such as kangaroos, wallabies and more, if the collision wasn’t intentional. You will be insured up to the amount covered of your car, as listed on your Certificate of Insurance. Make sure to provide any images/dashcam video evidence when you make a claim.Third Party Property Damage and Compulsory Third Party (CTP) Insurance, on the other hand, will not cover damage to your vehicle as a result of an incident. However, if you or your passenger are injured in a not-at-fault collision with wildlife, CTP insurance and Third Party Property may cover associated rehabilitation and medical expenses. Conditions and exclusions apply, so make sure to read your relevant policy document. Learn more about Comprehensive Car Insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/am-i-covered-for-collisions-with-wildlife.html](https://www.aami.com.au/faq/am-i-covered-for-collisions-with-wildlife.html)\n\n---",
