    "id": "faq-aami-37",
    "content": "## Question 36: Is an AAMI Home Assist callout considered a claim?\n**Insurer:** AAMI | **ID:** `aami-034`\n\n### Official Guidance\nNo, an AAMI Home Assist callout is not identified as a claim under your policy. Therefore, there is no excess payable for an AAMI Home Assist callout.Learn more about home assist\n\n*Canonical Source:* [https://www.aami.com.au/faq/is-an-aami-home-assist-callout-considered-a-claim.html](https://www.aami.com.au/faq/is-an-aami-home-assist-callout-considered-a-claim.html)\n\n---",
