    "id": "faq-aami-38",
    "content": "## Question 37: Why am I being charged an Emergency Services Levy (ESL) on my premium?\n**Insurer:** AAMI | **ID:** `aami-035`\n\n### Official Guidance\nIf you’re an AAMI customer, you may find your total premium is higher than last year. This may be due to the Emergency Services Levy (ESL). The levy is charged by other NSW insurers as well. The money contributed to the ESL by insurers is used to meet funding obligations to the NSW State Government. This funds vital NSW emergency services, including Fire and Rescue NSW, the NSW Rural Fire Services, and the NSW Emergency Services and the NSW State Government has increased what’s required to fund these services.Your quote, new business or your renewal schedule will display the amount of ESL you are required to pay.To learn more about how this levy might impact the cost of your insurance, please get in contact with us. You can also learn more about the ESL in general, by:Visiting the NSW Government Revenue ESL information page\n\n*Canonical Source:* [https://www.aami.com.au/faq/why-am-i-being-charged-an-emergency-services-levy-esl-on-my-premium.html](https://www.aami.com.au/faq/why-am-i-being-charged-an-emergency-services-levy-esl-on-my-premium.html)\n\n---",
