    "id": "faq-aami-39",
    "content": "## Question 38: What's the relationship between AAMI Health Insurance and nib health funds?\n**Insurer:** AAMI | **ID:** `aami-036`\n\n### Official Guidance\nAAMI Health Insurance is issued by nib health funds limited ABN 83 000 124 381 (nib), a registered private health insurer, and is marketed by Platform CoVentures Pty Ltd ABN 82 626 829 623 (PC), a Suncorp Group company. PC is an authorised agent of nib and receives commission from nib.\n\n*Canonical Source:* [https://www.aami.com.au/faq/whats-the-relationship-between-aami-health-insurance-and-nib-health-funds.html](https://www.aami.com.au/faq/whats-the-relationship-between-aami-health-insurance-and-nib-health-funds.html)\n\n---",
