    "id": "faq-aami-40",
    "content": "## Question 39: How do I update my Home Insurance cover?\n**Insurer:** AAMI | **ID:** `aami-037`\n\n### Official Guidance\nTo make your life easier, you can make a number of changes to your AAMI Home Insurance policy online. Through My Account, you can:update how much your contents and home are insured forupdate your Extra Cover Portable valuables - unspecified itemsupdate your personal details,and much more.Simply log in, click on ‘Update my policy’, and select the relevant policy you want to update.Some of the things that can’t be altered online include:changing your cover type (for example, from Property Owner to Landlord), andchanging the Extra Cover Portable valuables listed on your cover, andupdating mortgagee detailsFor these things, please give us a call on 13 22 44 and we’ll happily help you out.\n\n*Canonical Source:* [https://www.aami.com.au/faq/how-do-i-update-my-home-insurance-cover.html](https://www.aami.com.au/faq/how-do-i-update-my-home-insurance-cover.html)\n\n---",
