    "id": "faq-aami-42",
    "content": "## Question 41: Can I renew my NSW CTP Insurance term to 6 months?\n**Insurer:** AAMI | **ID:** `aami-039`\n\n### Official Guidance\nIf you have a light vehicle (vehicles with GVM less than 4.5 tonnes), you have the option to choose between a 6 month or 12 month term.As long as you pay for both the CTP Insurance and registration within 21 days of the due date, you can choose a 6 month term for the renewal of your CTP.If it’s been more than 21 days since your registration was due, you can only choose the 12 month period, unless there are ‘extenuating circumstances’ for us to accept the late payment.Learn more about CTP green slips\n\n*Canonical Source:* [https://www.aami.com.au/faq/can-i-renew-my-nsw-ctp-insurance-term-to-6-months.html](https://www.aami.com.au/faq/can-i-renew-my-nsw-ctp-insurance-term-to-6-months.html)\n\n---",
