    "id": "faq-aami-43",
    "content": "## Question 42: Why do I need Excess-Free Glass cover? I thought I already had cover for glass breakage under my policy?\n**Insurer:** AAMI | **ID:** `aami-040`\n\n### Official Guidance\nYes, accidental glass breakage is automatically covered under your policy. However, when you make a claim, you will need to pay the excess that applies to your policy. When you have Excess-free Glass cover, you do not pay an excess when you make a claim.Refer to the PDS for more information.\n\n*Canonical Source:* [https://www.aami.com.au/faq/why-do-i-need-excess-free-glass-cover-i-thought-i-already-had-cover-for-glass-breakage-under-my-policy.html](https://www.aami.com.au/faq/why-do-i-need-excess-free-glass-cover-i-thought-i-already-had-cover-for-glass-breakage-under-my-policy.html)\n\n---",
