    "id": "faq-aami-44",
    "content": "## Question 43: Can I update my insurance policy online?\n**Insurer:** AAMI | **ID:** `aami-041`\n\n### Official Guidance\nAAMI has made it easy for you to update most of your policy details online. Simply log in to My Account and click the ‘My policy list’ link. This will take you to a list of your AAMI policies, where you can click on the link to ‘Update my policy’.Please note: A few of our policies, such as Life Insurance and Income Protection, can’t be updated using our online system. Please call us on 13 22 44 if you'd like make changes.\n\n*Canonical Source:* [https://www.aami.com.au/faq/can-i-update-my-insurance-policy-online.html](https://www.aami.com.au/faq/can-i-update-my-insurance-policy-online.html)\n\n---",
