    "id": "faq-aami-45",
    "content": "## Question 44: Will AAMI waive the excess on Landlord Insurance policies if the tenant is unable to pay rent?\n**Insurer:** AAMI | **ID:** `aami-042`\n\n### Official Guidance\nAll standard excesses will still apply for AAMI Landlord Insurance policies if a tenant is unable to pay their rent.Refer to the PDS for more information\n\n*Canonical Source:* [https://www.aami.com.au/faq/will-aami-waive-the-excess-on-landlord-insurance-policies-if-the-tenant-is-unable-to-pay-rent.html](https://www.aami.com.au/faq/will-aami-waive-the-excess-on-landlord-insurance-policies-if-the-tenant-is-unable-to-pay-rent.html)\n\n---",
