    "id": "faq-aami-46",
    "content": "## Question 45: What is an ITCE% and why is it deducted?\n**Insurer:** AAMI | **ID:** `aami-043`\n\n### Official Guidance\nYou must tell us about the Input Tax Credits (ITC) you’re entitled to for your premium and claim, every time you make a claim. If you’re unsure, please confirm with your accountant. When we calculate a payment to you for your claim, we may reduce it by any ITC you are, or would be, entitled to receive.If you don’t tell us of your entitlement, or the information you give us is incorrect, we won’t cover you for any resulting fines, penalties or tax liability incurred.\n\n*Canonical Source:* [https://www.aami.com.au/faq/what-is-an-itce-and-why-is-it-deducted.html](https://www.aami.com.au/faq/what-is-an-itce-and-why-is-it-deducted.html)\n\n---",
