    "id": "faq-aami-48",
    "content": "## Question 47: Can unlisted drivers be covered in the event of an accident?\n**Insurer:** AAMI | **ID:** `aami-045`\n\n### Official Guidance\nWhether or not an unlisted driver might be covered in the event of an accident can depend on if the driver is legally allowed to drive the car. For example, P-Platers driving turbocharged cars that are over state regulated power-to-weight ratio limits would not be covered.If the driver is legally allowed to drive the car, you may still be able to make a claim, however you may incur an unlisted driver excess.If you’re looking to add a listed driver to your policy, this article has a step-by-step guide on how to do so.For more information, please call 13 22 44.Learn more about Car Insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/can-unlisted-drivers-be-covered-in-the-event-of-an-accident.html](https://www.aami.com.au/faq/can-unlisted-drivers-be-covered-in-the-event-of-an-accident.html)\n\n---",
