    "id": "faq-aami-49",
    "content": "## Question 48: How much Life Insurance cover do I need?\n**Insurer:** AAMI | **ID:** `aami-046`\n\n### Official Guidance\nWorking out how much Life Insurance cover you’ll need really varies across each person. One approach is to think about how much you can realistically afford to pay for cover each month, taking into consideration your existing expenses. An alternate approach may be to consider your current debts and future expenses like your mortgage or rent, living expenses, child care costs, schooling fees, etc.Learn more about life insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/how-much-life-insurance-cover-do-i-need.html](https://www.aami.com.au/faq/how-much-life-insurance-cover-do-i-need.html)\n\n---",
