    "id": "faq-aami-50",
    "content": "## Question 49: Am I covered for contents and stock I take from the office to work at home?\n**Insurer:** AAMI | **ID:** `aami-047`\n\n### Official Guidance\nIf you have purchased Property Damage Cover and/or Theft Cover, your policy provides the Additional benefit of ‘Temporary removal of stock and/or contents’. Cover is provided whilst stock and/or contents are temporarily removed from your business premises to another premises, such as your home, for up to 90 days.Exclusions apply. Check your policy schedule and PDS for limits and full details of these Additional benefits.\n\n*Canonical Source:* [https://www.aami.com.au/faq/am-i-covered-for-contents-and-stock-i-take-from-the-office-to-work-at-home.html](https://www.aami.com.au/faq/am-i-covered-for-contents-and-stock-i-take-from-the-office-to-work-at-home.html)\n\n---",
