    "id": "faq-aami-51",
    "content": "## Question 50: How do I find my VIN?\n**Insurer:** AAMI | **ID:** `aami-048`\n\n### Official Guidance\nYour Vehicle Identification Number (VIN) is your vehicle’s unique 17 character code. It can be used when tracking recalls, registrations, warranties, claims and theft. Your VIN can be located in a few places inside and outside your vehicle:Where the corner of the dashboard meets the windshield on the driver’s side.The door post (where the door latches when it’s closed) on the driver’s side.At the front of the engine block (under your bonnet).At the front end of the frame behind the driver’s side tyre.Inside of the driver’s side door jamb (where the door connects to the body of the car).If you still can’t find it, check your vehicle’s registration certificate or the owner’s manual (if you have it). You can also call the dealership or manufacturer, give them the make and model of your vehicle and ask where the VIN is located. Learn more about car insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/how-do-i-find-my-vin.html](https://www.aami.com.au/faq/how-do-i-find-my-vin.html)\n\n---",
