    "id": "faq-aami-54",
    "content": "## Question 53: Are trailers and caravans included in my CTP or MAI Insurance cover?\n**Insurer:** AAMI | **ID:** `aami-051`\n\n### Official Guidance\nAs long as your trailer and/or caravan is in a roadworthy condition, it will be covered by the CTP or MAI Insurance policy of the vehicle towing it.Learn more about CTP insurance Learn more about ACT MAI Insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/are-trailers-and-caravans-included-in-my-ctp-or-mai-insurance-cover.html](https://www.aami.com.au/faq/are-trailers-and-caravans-included-in-my-ctp-or-mai-insurance-cover.html)\n\n---",
