    "id": "faq-aami-57",
    "content": "## Question 56: Can a family member update my home insurance policy?\n**Insurer:** AAMI | **ID:** `aami-054`\n\n### Official Guidance\nIf you want for someone other than yourself (the policy holder) to be able to make changes to your home insurance policy, you’ll need to list them as a nominated representative. You can do that easily by calling us on 13 22 44. You can also email us at aami@aami.com.au, although response time is generally longer, so if it’s urgent it’s better to call.In your email, make sure you include the following details:Your full name (first and last name)Your date of birthYour full addressAs well as your your nominated representative's:full namedate of birth, andphone number Learn more about Home Insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/can-a-family-member-update-my-home-insurance-policy.html](https://www.aami.com.au/faq/can-a-family-member-update-my-home-insurance-policy.html)\n\n---",
