    "id": "faq-aami-58",
    "content": "## Question 57: How do I get a CTP Green Slip?\n**Insurer:** AAMI | **ID:** `aami-055`\n\n### Official Guidance\nGetting a NSW CTP insurance policy (Green Slip) is easy!You can get a quote online with AAMI in minutes. Once you do, we’ll send confirmation directly to Transport for NSW so you can complete your vehicle registration.Get a Green Slip quote in minutes\n\n*Canonical Source:* [https://www.aami.com.au/faq/how-do-i-get-a-ctp-green-slip.html](https://www.aami.com.au/faq/how-do-i-get-a-ctp-green-slip.html)\n\n---",
