    "id": "faq-aami-59",
    "content": "## Question 58: How can I pay for my NSW CTP?\n**Insurer:** AAMI | **ID:** `aami-056`\n\n### Official Guidance\nAAMI makes it easy to pay your CTP Insurance (also known as Green Slip) with three convenient payment options. Choose to pay online (with a Visa, MasterCard, or American Express), over the phone, or at your nearest Australia Post Office – whatever works for you. Check out all the ways you can pay for your NSW CTP insurance.Pay or renew your CTP Insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/how-can-i-pay-for-my-nsw-ctp.html](https://www.aami.com.au/faq/how-can-i-pay-for-my-nsw-ctp.html)\n\n---",
