    "id": "faq-aami-61",
    "content": "## Question 60: What caravan modifications do I need to let you know about?\n**Insurer:** AAMI | **ID:** `aami-058`\n\n### Official Guidance\nMany modern caravans come with extra modifications as a standard, including solar panels, external showers and kitchens, air conditioning, and TV antennas. These don’t generally need to be reported to us when getting a quote. If you’ve had a non-standard modification fitted, like wheelchair access, please call us on 13 22 44 so that we can make sure it’s included in the total amount covered for the caravan. Learn more about caravan insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/what-caravan-modifications-do-i-need-to-let-you-know-about.html](https://www.aami.com.au/faq/what-caravan-modifications-do-i-need-to-let-you-know-about.html)\n\n---",
