    "id": "faq-aami-62",
    "content": "## Question 61: What are the hours of operation for an AAMI Home Assist callout?\n**Insurer:** AAMI | **ID:** `aami-059`\n\n### Official Guidance\nAAMI Home Assist can be contacted 24 hours a day, 7 days a week. Our support team will be able to assess the emergency. Assistance will be provided as quickly as possible, but during certain hours there may be limited availability. The response time will depend on a variety of factors including severity, location of your insured address and the demand for AAMI Home Assist at that time.Learn more about home assist\n\n*Canonical Source:* [https://www.aami.com.au/faq/what-are-the-hours-of-operation-for-an-aami-home-assist-callout.html](https://www.aami.com.au/faq/what-are-the-hours-of-operation-for-an-aami-home-assist-callout.html)\n\n---",
