    "id": "faq-aami-65",
    "content": "## Question 64: I have damage to my roof and windows from a recent storm. How do I make a claim?\n**Insurer:** AAMI | **ID:** `aami-062`\n\n### Official Guidance\nMake a claim online or in the AAMI App, 24/7. This will cover both the roof and windows under the one claim. Once the claim is finalised, you’ll need to pay any excess that applies to your policy\n\n*Canonical Source:* [https://www.aami.com.au/faq/i-have-damage-to-my-roof-and-windows-from-a-recent-storm-how-do-i-make-a-claim.html](https://www.aami.com.au/faq/i-have-damage-to-my-roof-and-windows-from-a-recent-storm-how-do-i-make-a-claim.html)\n\n---",
