    "id": "faq-aami-66",
    "content": "## Question 65: Can I still insure my caravan if it's unoccupied?\n**Insurer:** AAMI | **ID:** `aami-063`\n\n### Official Guidance\nYou don’t have to be currently living/using your caravan to insure it with AAMI. The only exception to this is if it’s been unoccupied for 60 days and will continue to be unoccupied for more than 6 months in a row. Learn more about caravan insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/can-i-still-insure-my-caravan-if-its-unoccupied.html](https://www.aami.com.au/faq/can-i-still-insure-my-caravan-if-its-unoccupied.html)\n\n---",
