    "id": "faq-aami-67",
    "content": "## Question 66: How long do Income Protection Insurance payments last?\n**Insurer:** AAMI | **ID:** `aami-064`\n\n### Official Guidance\nFor the Sickness and Injury cover, it depends on the benefit period you have chosen. Each time you make a claim that's accepted, you can be paid for up to 5 years, as long as you’re still unable to work due to the sickness or injury during that time.You can claim as many times as you need over the life of the policy. The payment of benefits is subject to the relevant terms that apply to your policy, including any exclusions or limitations - check out the Combined Product Disclosure Statement (PDS) and Financial Services Guide (FSG) to find out more.Learn more about income protection\n\n*Canonical Source:* [https://www.aami.com.au/faq/how-long-do-income-protection-insurance-payments-last.html](https://www.aami.com.au/faq/how-long-do-income-protection-insurance-payments-last.html)\n\n---",
