    "id": "faq-aami-68",
    "content": "## Question 67: What happens to my ACT MAI Insurance when I sell or buy a vehicle that is registered?\n**Insurer:** AAMI | **ID:** `aami-065`\n\n### Official Guidance\nMAI Insurance is linked to the vehicle, not the owner. If you sell your vehicle, the MAI Insurance will be transferred to the new owner. Similarly, if you buy a vehicle, the MAI Insurance will be transferred to you. Just make sure that you advise Access Canberra. Learn more about MAI insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/what-happens-to-my-act-mai-insurance-when-i-sell-or-buy-a-vehicle-that-is-registered.html](https://www.aami.com.au/faq/what-happens-to-my-act-mai-insurance-when-i-sell-or-buy-a-vehicle-that-is-registered.html)\n\n---",
