    "id": "faq-aami-69",
    "content": "## Question 68: The excess on my building policy is higher than it costs to fix a window that has been accidently broken. What can I do?\n**Insurer:** AAMI | **ID:** `aami-066`\n\n### Official Guidance\nIf you have Optional Excess-free Glass Cover as part of your building insurance and a window is accidentally broken, you can claim under this option and no excess applies.Remember you can only claim for the window if there was no damage before you added on the optional cover.Refer to the PDS for more information\n\n*Canonical Source:* [https://www.aami.com.au/faq/the-excess-on-my-building-policy-is-higher-than-it-costs-to-fix-a-window-that-has-been-accidently-broken--what-can-i-do.html](https://www.aami.com.au/faq/the-excess-on-my-building-policy-is-higher-than-it-costs-to-fix-a-window-that-has-been-accidently-broken--what-can-i-do.html)\n\n---",
