    "id": "faq-aami-70",
    "content": "## Question 69: When do my payments start after my Income Protection claim is approved?\n**Insurer:** AAMI | **ID:** `aami-067`\n\n### Official Guidance\nStarting from the date the medical practitioner gives you your diagnosis, a claim waiting period applies, and from then payments are made monthly in arrears. The claim waiting period is the amount of time you must be off work due to sickness or injury before benefits are payable. For the sickness and injury cover, stopping work must be due to sickness or injury. Some extra conditions apply – make sure you read the Combined Product Disclosure Statement (PDS) and Financial Services Guide (FSG) for all the details.If you go back to work during a month you’re claiming, you’ll receive a portion of the monthly amount for the time you weren’t able to work. While you’re receiving your monthly benefit, we’ll let you take a break from paying your regular premiums so your income isn’t reduced.Learn more about income protection\n\n*Canonical Source:* [https://www.aami.com.au/faq/when-do-my-payments-start-after-my-income-protection-claim-is-approved.html](https://www.aami.com.au/faq/when-do-my-payments-start-after-my-income-protection-claim-is-approved.html)\n\n---",
