    "id": "faq-aami-71",
    "content": "## Question 70: Is my work laptop covered away from the office by my Home and Contents Insurance?\n**Insurer:** AAMI | **ID:** `aami-068`\n\n### Official Guidance\nIf you've taken a laptop home from your employer's office, it's then considered your responsibility while it's away from the insured address (say, the office). This means the laptop will then be covered under your AAMI Home and Contents Insurance while you're using it from home.This only extends to cover at home, so please contact us by calling 13 22 44 or click that chat icon to speak to someone online if you're using your laptop elsewhere and would like cover for it. Learn more about home insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/is-my-work-laptop-covered-away-from-the-office-by-my-home-and-contents-insurance.html](https://www.aami.com.au/faq/is-my-work-laptop-covered-away-from-the-office-by-my-home-and-contents-insurance.html)\n\n---",
