    "id": "faq-aami-72",
    "content": "## Question 71: How do safety checks and inspections work?\n**Insurer:** AAMI | **ID:** `aami-069`\n\n### Official Guidance\nSafety checks can only be performed at authorised inspection stations, and the results are sent to Service NSW electronically.Pink Slip: To renew registration in NSW, most light vehicles that are more than 5 years old must undergo a safety check (pink slip) to ensure they meet minimum safety requirements.Blue Slip: All unregistered light vehicles need a blue slip inspection before they can be registered.Learn more about CTP insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/how-do-safety-checks-and-inspections-work.html](https://www.aami.com.au/faq/how-do-safety-checks-and-inspections-work.html)\n\n---",
