    "id": "faq-aami-73",
    "content": "## Question 72: What's a waiting period?\n**Insurer:** AAMI | **ID:** `aami-070`\n\n### Official Guidance\nThe waiting period for AAMI Income Protection is the amount of time that must pass before your monthly benefit payments start. It has to be a consecutive number of days that passes in which you’re eligible to be covered by your Income Protection policy; for example you’re injured or sick for that whole time, you continue to not be employed during that period.Learn more about income protection\n\n*Canonical Source:* [https://www.aami.com.au/faq/whats-a-waiting-period.html](https://www.aami.com.au/faq/whats-a-waiting-period.html)\n\n---",
