    "id": "faq-aami-74",
    "content": "## Question 73: Can I add a child to my Health cover?\n**Insurer:** AAMI | **ID:** `aami-071`\n\n### Official Guidance\nYes, you can, as long as the child you’re adding is classified as a dependant for family health insurance purposes. This could include a child under the age of 21 or a student dependant who is studying full time and under 31. To add a child (or find out if they count as a dependent), please contact us on 13 22 44. Learn more about health insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/can-i-add-a-child-to-my-health-cover.html](https://www.aami.com.au/faq/can-i-add-a-child-to-my-health-cover.html)\n\n---",
