    "id": "faq-aami-75",
    "content": "## Question 74: Does AAMI Home Assist allow me to use my own tradesperson?\n**Insurer:** AAMI | **ID:** `aami-072`\n\n### Official Guidance\nNo, as part of the agreement only a qualified AAMI Home Assist tradesperson can be used. AAMI Home Assist will provide a qualified tradesperson to attend to any callout.Learn more about home assist\n\n*Canonical Source:* [https://www.aami.com.au/faq/does-aami-home-assist-allow-me-to-use-my-own-tradesperson.html](https://www.aami.com.au/faq/does-aami-home-assist-allow-me-to-use-my-own-tradesperson.html)\n\n---",
