    "id": "faq-aami-76",
    "content": "## Question 75: What is the process if an AAMI Home Assist repair exceeds the 2 hours labour and $50 materials limits?\n**Insurer:** AAMI | **ID:** `aami-073`\n\n### Official Guidance\nMost home emergencies are able to be fixed (to the extent that no further damage is being caused) within the 2 hour allocation. Where we are unable to complete the required repairs within the 2 hour limit and/or the materials exceed $50, the attending Tradesperson will inform you of potential options.Learn more about home assist\n\n*Canonical Source:* [https://www.aami.com.au/faq/what-is-the-process-if-an-aami-home-assist-repair-exceeds-the-2-hours-labour-and-50-materials-limits.html](https://www.aami.com.au/faq/what-is-the-process-if-an-aami-home-assist-repair-exceeds-the-2-hours-labour-and-50-materials-limits.html)\n\n---",
