    "content": "## Question 77: How do I call AAMI?\n**Insurer:** AAMI | **ID:** `aami-075`\n\n### Official Guidance\nTo get in touch with us by phone, please go to the Contact Us page for details. Alternatively, you can also chat to us online via the Contact Us page.We also have different numbers for more specific topics and problems—you can find a full directory on our Contact Us page.\n\n*Canonical Source:* [https://www.aami.com.au/faq/how-do-i-call-aami.html](https://www.aami.com.au/faq/how-do-i-call-aami.html)\n\n---",
