    "id": "faq-aami-79",
    "content": "## Question 78: Can I get a discount on AAMI Life Insurance for having more than one policy with AAMI?\n**Insurer:** AAMI | **ID:** `aami-076`\n\n### Official Guidance\nYes, if you hold other AAMI branded Insurance policies such as car insurance, we will apply a 5% discount on your AAMI Life Insurance premium for the life of the policy.In addition, if you add another adult to your policy, the youngest person will receive a 5% discount. The family discount doesn't apply to the Optional Illness Covers.Learn more about life insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/can-i-get-a-discount-on-aami-life-insurance-for-having-more-than-one-policy-with-aami.html](https://www.aami.com.au/faq/can-i-get-a-discount-on-aami-life-insurance-for-having-more-than-one-policy-with-aami.html)\n\n---",
