    "id": "faq-aami-80",
    "content": "## Question 79: Is Income Protection tax deductible?\n**Insurer:** AAMI | **ID:** `aami-077`\n\n### Official Guidance\nMost of the time, income protection premiums are tax deductible if you’re working (depending on a few individual circumstances). That means at tax time you may be able to claim your premium as a deduction and potentially save money.Learn more about income protection\n\n*Canonical Source:* [https://www.aami.com.au/faq/is-income-protection-tax-deductible.html](https://www.aami.com.au/faq/is-income-protection-tax-deductible.html)\n\n---",
