    "id": "faq-aami-86",
    "content": "## Question 85: Do you cover vaccinations?\n**Insurer:** AAMI | **ID:** `aami-083`\n\n### Official Guidance\nA $50 benefit for vaccinations (as well as flea/tick/ blood screen) is available if you select Routine Care, which is an option available with any of our pet insurance policies.Routine Care also offers a $100 benefit for the following treatments and processes:DesexingMicrochippingHeartworm controlTeeth cleaningPrescription dietsCremation or burialDental illness treatmentCouncil registration feesObedience trainingBehavioural therapyAlternative therapiesLearn more about health insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/do-you-cover-vaccinations.html](https://www.aami.com.au/faq/do-you-cover-vaccinations.html)\n\n---",
