    "id": "faq-aami-87",
    "content": "## Question 86: Do I need Life Insurance on top of my super?\n**Insurer:** AAMI | **ID:** `aami-084`\n\n### Official Guidance\nMost super funds offer at least a basic level of life insurance, as well as income protection and Total Permanent Disability (TPD) insurance to protect members and their families from the financial hardship of death or a terminal illness.The level of cover and types of insurance provided through your super are limited. Payments are also sometimes delayed after you’ve made a claim, and coverage ends after you reach a certain age (usually 65 or 70). Read more about the pros and cons about using the life insurance included with your super fund at Money Smart. Learn more about life insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/do-i-need-life-insurance-on-top-of-my-super.html](https://www.aami.com.au/faq/do-i-need-life-insurance-on-top-of-my-super.html)\n\n---",
