    "id": "faq-aami-92",
    "content": "## Question 91: What is an annual limit?\n**Insurer:** AAMI | **ID:** `aami-089`\n\n### Official Guidance\nExtras Health Cover annual limits are the maximum amount you can claim on a particular service per calendar year. These limits vary depending on your level of extras health cover and what service you’re claiming for. For example, with the Premium Active Extras Cover there’s an annual limit of $500 on physio. Learn more about health insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/what-is-an-annual-limit.html](https://www.aami.com.au/faq/what-is-an-annual-limit.html)\n\n---",
