    "id": "faq-aami-93",
    "content": "## Question 92: How do I know if my policy is active?\n**Insurer:** AAMI | **ID:** `aami-090`\n\n### Official Guidance\nFor Home and Contents, Landlord, Car and Business Insurance policy holders, you can check the current status of your policy cycle through your My Account. You’ll need to add your policy into your My Account first, which you can do by clicking ‘Add policy’ and entering your policy details. After that’s done, you can check your valid policy dates by selecting ‘View policy’. Can’t seem to add your policy or don’t have your policy details? Don’t stress! Simply call 13 22 44 to speak to one of our customer service representatives.\n\n*Canonical Source:* [https://www.aami.com.au/faq/how-do-i-know-if-my-policy-is-active.html](https://www.aami.com.au/faq/how-do-i-know-if-my-policy-is-active.html)\n\n---",
