    "id": "faq-aami-95",
    "content": "## Question 94: Will I be covered for Cosmetic Surgery?\n**Insurer:** AAMI | **ID:** `aami-092`\n\n### Official Guidance\nNo, none of our Health Insurance covers provide payments towards procedures or hospital costs associated with cosmetic surgery to enhance appearance. Learn more about health insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/will-i-be-covered-for-cosmetic-surgery.html](https://www.aami.com.au/faq/will-i-be-covered-for-cosmetic-surgery.html)\n\n---",
