    "id": "faq-aami-97",
    "content": "## Question 96: Can I make a claim for the same sickness/injury that I have before?\n**Insurer:** AAMI | **ID:** `aami-094`\n\n### Official Guidance\nIf you suffer from the same or related sickness or injury that you have previously claimed for within 6 months of your last benefit being payable, we will recommence benefit payments without applying a new waiting period. These benefits will be added to the remaining benefit period to ensure the maximum payment under the benefit period is not exceeded. If you’ve made a full recovery in between claims then you will commence a new claim and the benefit period will restart.FAQs & HelpPDS Library\n\n*Canonical Source:* [https://www.aami.com.au/faq/can-i-make-a-claim-for-the-same-sicknessinjury-that-i-have-before.html](https://www.aami.com.au/faq/can-i-make-a-claim-for-the-same-sicknessinjury-that-i-have-before.html)\n\n---",
