    "id": "faq-aami-98",
    "content": "## Question 97: Do I have to tell you if my income changes?\n**Insurer:** AAMI | **ID:** `aami-095`\n\n### Official Guidance\nThe amount you get paid if you’re off work is dependent on your income, so it’s important you let us know if that changes. All you have to do is contact us on 1300 407 322 and we’ll help you out.Learn more about income protection\n\n*Canonical Source:* [https://www.aami.com.au/faq/do-i-have-to-tell-you-if-my-income-changes.html](https://www.aami.com.au/faq/do-i-have-to-tell-you-if-my-income-changes.html)\n\n---",
