    "id": "faq-aami-99",
    "content": "## Question 98: Can I reduce the cost of my Life Insurance?\n**Insurer:** AAMI | **ID:** `aami-096`\n\n### Official Guidance\nYour premium, i.e. the purchase cost of your Life Insurance, is calculated by a number of factors. These can include:GenderAgeWeightSmoking statusPre-existing health conditionsEngagement in hazardous sports such as parachuting, mountaineering and motor sportsCertain lifestyle changes, like quitting smoking, changing jobs, or losing weight may mean your premium is lessened, so it’s important to keep us in the loop as often as you can by calling 1300 407 322.Learn more about life insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/can-i-reduce-the-cost-of-my-life-insurance.html](https://www.aami.com.au/faq/can-i-reduce-the-cost-of-my-life-insurance.html)\n\n---",
