    "id": "faq-aami-100",
    "content": "## Question 99: What happens if I suspend my Health cover?\n**Insurer:** AAMI | **ID:** `aami-097`\n\n### Official Guidance\nWhen you suspend your Hospital Cover, it’s basically on hold. That means you aren’t charged premiums, but you also can’t make claims for any services or treatments you receive within the suspension period.You can request to suspend your health cover for one of two reasons – if you are experiencing financial hardship or if you are travelling overseas for a period longer than 2 months. To be eligible, you must have had your AAMI Health Insurance policy for 12 continuous months prior to applying for a suspension and premiums must be financially up to date.Learn more about health insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/what-happens-if-i-suspend-my-health-cover.html](https://www.aami.com.au/faq/what-happens-if-i-suspend-my-health-cover.html)\n\n---",
