    "id": "faq-aami-101",
    "content": "## Question 100: What's an out-of-pocket expense, and can I reduce mine?\n**Insurer:** AAMI | **ID:** `aami-098`\n\n### Official Guidance\nAn out-of-pocket expense is the difference between what we'll cover and the total cost of your stay in hospital. For example, if your stay in hospital costs more than what you're covered for, you'll need to pay an out-of-pocket expense.There are ways we can help you reduce or even avoid out-of-pocket expenses altogether, including:Checking if you have the right level of coverProviding you with access to a network of Agreement Private HospitalsHelping to cap doctor’s costs with nib’s MediGap SchemeContact Us to find out moreLearn more about health insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/whats-an-out-of-pocket-expense-and-can-i-reduce-mine.html](https://www.aami.com.au/faq/whats-an-out-of-pocket-expense-and-can-i-reduce-mine.html)\n\n---",
