    "id": "faq-aami-102",
    "content": "## Question 101: How often should I review my Health Insurance cover?\n**Insurer:** AAMI | **ID:** `aami-099`\n\n### Official Guidance\nYou should review your Health Insurance at least once a year or when your circumstances change, to make sure you’re getting the most out of your cover. Reviewing what you are and aren’t covered for is also a great way to assess whether you’re paying for services you don’t use.Learn more about health insurance\n\n*Canonical Source:* [https://www.aami.com.au/faq/how-often-should-i-review-my-health-insurance-cover.html](https://www.aami.com.au/faq/how-often-should-i-review-my-health-insurance-cover.html)\n\n---",
