    "id": "faq-aami-103",
    "content": "## Question 102: Does AAMI comply with the Life Insurance Code of Practice?\n**Insurer:** AAMI | **ID:** `aami-100`\n\n### Official Guidance\nDefinitely! It’s important to us that you get the highest standards of service when dealing with us, so we adopt the industry’s Life Insurance Code of Practice.\n\n*Canonical Source:* [https://www.aami.com.au/faq/does-aami-comply-with-the-life-insurance-code-of-practice.html](https://www.aami.com.au/faq/does-aami-comply-with-the-life-insurance-code-of-practice.html)\n\n---\n\n\n### Regulatory Warning (Corporations Act 2001 Section 949A)\n⚠️ General Advice Warning: This information is general factual information only and does not take into account your personal objectives, financial situation, or needs. Before making any financial decision, you should read the relevant Product Disclosure Statement (PDS) and Target Market Determination (TMD) and seek independent advice.",
